import json
import os
from pathlib import Path
import subprocess

path=Path('/tmp/rules-checking-trap-glyph-timings.json')
results=json.loads(path.read_text())
for row in results['samples']:
    row['batch']=0
for batch in (1,2):
    for case in ('glyph','traps'):
        for side in (('after','before') if batch == 1 else ('before','after')):
            root=Path('/tmp/rules-checking-trap-glyph-'+side)
            env={**os.environ,'PYTHONPATH':str(root),'PYTHONDONTWRITEBYTECODE':'1','PYTHONHASHSEED':'71'}
            completed=subprocess.run(['/home/tommaso/.cache/dnd-engine/venv/bin/python',
                '/tmp/rules-checking-trap-glyph-timing.py','--case',case],cwd=root,env=env,text=True,capture_output=True,timeout=120)
            Path(f'/tmp/trap-glyph-{side}-{case}-batch{batch}.log').write_text(completed.stdout+completed.stderr)
            if completed.returncode:
                raise RuntimeError(completed.stderr[-3000:])
            for line in completed.stdout.splitlines():
                if line.startswith('{'):
                    results['samples'].append({**json.loads(line),'side':side,'batch':batch})
            path.write_text(json.dumps(results,indent=2))
            print(case,side,'batch',batch,'completed',flush=True)
